// 코드 분할: core.js(헬퍼+엔진) + 도구별 t-<id>.js — 페이지가 자기 도구 코드만 받는다
const toolBody = toolsArr.slice(toolsArr.indexOf("[")+1, toolsArr.lastIndexOf("]")); // TOOLS=[ ... ] 내부
const markers = [];
{ let i = 0; const re = /\n  \{id:"([^"]+)"/g; let m;
  while ((m = re.exec(toolBody))) markers.push({ id: m[1], at: m.index }); }
if (markers.length !== meta.length)
  throw new Error(`도구 분할 실패: 마커 ${markers.length} ≠ 메타 ${meta.length}`);
const chunks = markers.map((mk, i) => {
  let src = toolBody.slice(mk.at, i + 1 < markers.length ? markers[i + 1].at : undefined).trim();
  if (src.endsWith(",")) src = src.slice(0, -1);
  return { id: mk.id, src };
});
const coreJs = `${helpers}\nvar TOOLS=[];\n`+
  `window.mountTool=function(id,elId){var t=TOOLS.filter(function(x){return x.id===id;})[0];if(!t)return;var el=document.getElementById(elId);t.render(el);if(location.hash==="#go"&&(id==="todayfortune"||id==="saju")){try{var hh=JSON.parse(sessionStorage.getItem("dnbs_hb")||"null"),bi=el.querySelector("#d");sessionStorage.removeItem("dnbs_hb");if(hh&&hh.v&&Date.now()-hh.t<6e5&&bi){bi.value=id==="todayfortune"?hh.v.replace(/-/g,"."):hh.v;bi.dispatchEvent(new Event("change",{bubbles:true}));}}catch(e){}}if(location.hash==="#go"){var g=el.querySelector("#go"),ni=el.querySelector("#d");if(g&&!(ni&&ni.inputMode==="numeric"&&!ni.value))setTimeout(function(){g.click();},250);}`+
  // 도구들은 <label>이름</label><input id=…> 로 쓰고 for 를 안 붙였다. 바로 뒤 입력칸과 이어 준다(스크린리더·라벨 클릭)
  // 생년월일은 이름표와 입력칸 사이에 연대 칩이 끼어 있어, 다음 이름표 전까지 형제를 따라가며 첫 입력칸을 찾는다
  // 결과 소제목(h3)은 페이지 h1 바로 아래에 나오므로 스크린리더에는 2단계로 읽히게 한다(결과는 클릭 뒤에 그려지니 변화를 지켜본다)
  `var lv=function(){[].forEach.call(el.querySelectorAll("h3:not([aria-level])"),function(h){h.setAttribute("aria-level","2");});};lv();if(window.MutationObserver)new MutationObserver(lv).observe(el,{childList:true,subtree:true});`+
  `var Q="input,select,textarea";[].forEach.call(el.querySelectorAll("label:not([for])"),function(l){if(l.querySelector(Q))return;var c=null;for(var n=l.nextElementSibling;n&&!c&&n.tagName!=="LABEL";n=n.nextElementSibling)c=n.matches(Q)?n:n.querySelector(Q);if(c&&c.id)l.htmlFor=c.id;});};`;
// 구문 파손 즉시 빌드 실패 (파싱만, 실행 안 함)
new Function(coreJs);
chunks.forEach(c => { try { new Function("TOOLS.push(" + c.src + ");"); } catch (e) { throw new Error("도구 청크 구문 오류: " + c.id + " — " + e.message); } });
// 캐시 무효화: js/css는 장기 캐시되므로 내용 해시를 쿼리로 붙인다 (파일명 고정 + ?v=해시)
const hash8 = s => require("crypto").createHash("md5").update(s).digest("hex").slice(0, 8);
const coreV = hash8(coreJs);
chunks.forEach(c => c.v = hash8(c.id === "lunar"
  ? fs.readFileSync(path.join(__dirname, "vendor-lunar.js"), "utf8") + c.src
  : c.src));

// 사이트맵 + robots
// lastmod가 없으면 크롤러가 재방문 시점을 잡을 근거가 없다. 빌드일을 찍는다.
// changefreq·priority는 구글이 무시하므로 넣지 않는다.
// 한국 사이트라 날짜는 KST 기준이어야 한다. toISOString 은 UTC 라
// KST 새벽에 빌드하면 lastmod 가 하루 뒤로 밀린다.
const KST_NOW = new Date(Date.now() + 9 * 3600 * 1000);
const BUILD_DAY = KST_NOW.toISOString().slice(0,10);
// 단, 빌드일을 전 페이지에 일괄로 찍으면 lastmod 가 전부 같아져 구글이 신호를 무시한다.
// 그래서 페이지의 보이는 글자(스크립트·스타일·태그 제외)가 바뀐 날만 새로 찍는다.
// 해시와 날짜는 lastmod.json 에 남긴다. 사이트맵 문자열은 페이지를 다 쓴 뒤 채운다.
// 전 페이지 공통 문구의 "자동 검증 N개"는 테스트가 늘 때마다 바뀌므로 해시에서 뺀다.
const LASTMOD_FILE = path.join(__dirname, "lastmod.json");
const pageText = html => html.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ").replace(/자동 검증 \d+개/g, "자동 검증 N개").replace(/\s+/g, " ").trim();
const smUrl = p => `<url><loc>${DOMAIN}/${p}</loc><lastmod>@@LASTMOD:${p}@@</lastmod></url>`;
let sitemap = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n`+
  smUrl("")+"\n"+pubMeta.map(t=>smUrl(t.id+".html")).join("\n")+"\n"+
  STAR_PAGES.map(s=>smUrl("star-"+s.en+".html")).join("\n")+"\n"+
  ZODIAC_PAGES.map(z=>smUrl("zodiac-"+z.en+".html")).join("\n")+"\n"+
  smUrl("tti-gunghap.html")+"\n"+TTI.JI.map(z=>smUrl(ttiHubUrl(z.i))).join("\n")+"\n"+TTI.PAIR_LIST.map(p=>smUrl(ttiPairUrl(p.a,p.b))).join("\n")+"\n"+
  ILGAN_PAGES.map(g=>smUrl("ilgan-"+g.en+".html")).join("\n")+"\n"+
  SIPSEONG_PAGES.map(s=>smUrl("sipseong-"+s.en+".html")).join("\n")+"\n"+
  TAROT_PAGES.map(c=>smUrl("tarot-"+c.en+".html")).join("\n")+"\n"+
  CONCEPT_PAGES.map(c=>smUrl("concept-"+c.en+".html")).join("\n")+"\n"+
  smUrl("learn.html")+"\n"+LEARN.LECTURES.filter(c=>c.en).map(c=>smUrl(c.page)).join("\n")+"\n"+
  smUrl("iljin.html")+"\n"+
  ILJU_PAGES.map(p=>smUrl("ilju-"+p.en+".html")).join("\n")+"\n"+
  smUrl("manse.html")+"\n"+smUrl("manse-howto.html")+"\n"+smUrl("dict.html")+"\n"+smUrl("dream.html")+"\n"+DREAM.map(c=>smUrl("dream-"+c.id+".html")).join("\n")+"\n"+
  MANSE_PAGES.filter(MANSE_KEEP).map(p=>smUrl("manse-"+p.en+".html")).join("\n")+"\n"+
  (COLUMN_PAGES.length ? smUrl("column.html")+"\n"+COLUMN_PAGES.map(c=>smUrl("column-"+c.en+".html")).join("\n")+"\n" : "")+
  SITE_PAGES.map(p=>smUrl(p.id+".html")).join("\n")+`\n</urlset>`;
const robots = `User-agent: *\nAllow: /\nSitemap: ${DOMAIN}/sitemap.xml\nSitemap: ${DOMAIN}/rss.xml`;

