/* RSS 2.0 — 네이버 서치어드바이저가 사이트맵과 별개로 받는 수집 경로.
   전 페이지를 넣지 않는다. 새로 늘어나는 구간(월력·일주·일진)과 주요 도구만
   추려 100개로 묶는다. 피드가 길수록 좋은 것이 아니라, 무엇이 새것인지
   알려주는 것이 목적이다. */
const RSS_DESC = "무료 사주팔자 만세력과 오늘의 운세·별자리 운세·띠별 운세·타로·궁합. 태양황경을 직접 계산하는 만세력 엔진으로 풀이합니다.";
const rssItem = (loc, title, desc) =>
  "<item><title>" + esc(title) + "</title>" +
  "<link>" + loc + "</link><guid isPermaLink=\"true\">" + loc + "</guid>" +
  "<pubDate>" + new Date().toUTCString() + "</pubDate>" +
  "<description>" + esc(desc) + "</description></item>";

const rssRows = [
  [DOMAIN + "/", "동네보살 — 무료 사주·운세 " + pubMeta.length + "가지", RSS_DESC],
  [DOMAIN + "/manse.html", "무료 만세력 — 사주 만세력 계산기", "생년월일시로 사주 여덟 글자와 대운을 계산하는 무료 만세력. 절기는 태양황경으로 직접 계산합니다."],
  [DOMAIN + "/manse-howto.html", "만세력 보는법 — 원국표 읽는 여섯 단계", "만세력 원국표를 오른쪽부터 읽는 법, 일간 찾기, 오행 세기, 십성과 대운을 예시로 풀었습니다."],
  ...TAROT_PAGES.map(c => [`${DOMAIN}/tarot-${c.en}.html`, `${c.ko} 카드 뜻`, `${c.keyword}. 정방향 ${c.upWords.join("·")}, 역방향 ${c.revWords.join("·")}.`]),
  ...COLUMN_PAGES.map(c => [`${DOMAIN}/column-${c.en}.html`, c.title, c.desc]),
  [DOMAIN + "/learn.html", "명리학 배우기 — 사주 기초부터 대운까지 16강", LEARN_HUB_DESC],
  ...LEARN.LECTURES.filter(c => c.en).map(c => [`${DOMAIN}/${c.page}`, c.title, c.desc]),
  // 지금 근처 24개월. slice(-24) 를 쓰면 배열 끝인 2029~2030 이 잡혀
  // 정작 사람들이 찾는 이번 달이 피드에서 빠진다.
  ...(() => {
    const now = new Date(Date.now() + 9 * 3600 * 1000);   // KST 기준 현재 달
    const i = MANSE_PAGES.findIndex(p => p.y === now.getUTCFullYear() && p.mo === now.getUTCMonth() + 1);
    const at = i < 0 ? 0 : Math.max(0, i - 6);
    return MANSE_PAGES.slice(at, at + 24).filter(MANSE_KEEP); // noindex 월력은 피드에 넣지 않는다
  })().map(p => [
    `${DOMAIN}/manse-${p.en}.html`, `${p.y}년 ${p.mo}월 만세력`,
    `${p.y}년 ${p.mo}월 날짜별 일진과 음력, ${MANSE_SRC.MONTH_TERMS[p.mo].join("·")} 절기 시각.`]),
  ...ILJU_PAGES.map(p => [
    `${DOMAIN}/ilju-${p.en}.html`, `${p.ko}일주 성격`,
    `${p.ko}일주(${p.han}) — 일간 ${p.gan.ko}${p.gan.el}, 배우자 자리 ${p.ji.ko}${p.ji.el}, 십이운성 ${p.un}.`]),
  ...ILGAN_PAGES.map(g => [
    `${DOMAIN}/ilgan-${g.en}.html`, `${g.ko}${g.el} 일간`, g.metaphor]),
].slice(0, 120);

const rss = `<?xml version="1.0" encoding="UTF-8"?>` +
  `<rss version="2.0"><channel>` +
  `<title>동네보살</title><link>${DOMAIN}/</link>` +
  `<description>${esc(RSS_DESC)}</description>` +
  `<language>ko</language><lastBuildDate>${new Date().toUTCString()}</lastBuildDate>` +
  rssRows.map(r => rssItem(r[0], r[1], r[2])).join("") +
  `</channel></rss>`;
fs.writeFileSync(path.join(OUT,"rss.xml"), rss);

const lastmod = fs.existsSync(LASTMOD_FILE) ? JSON.parse(fs.readFileSync(LASTMOD_FILE, "utf8")) : {};
sitemap = sitemap.replace(/@@LASTMOD:([^@]*)@@/g, (_, p) => {
  const file = p || "index.html";
  const h = hash8(pageText(fs.readFileSync(path.join(OUT, file), "utf8")));
  if (!lastmod[file] || lastmod[file].h !== h) lastmod[file] = { h, d: BUILD_DAY };
  return lastmod[file].d;
});
